#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

#define CHILD_EXIT_CODE 42

int main() {
    pid_t child_pid;
    int status;

    child_pid = fork();

    if (child_pid == -1) {
        perror("fork error");
        return 1;
    }

    if (child_pid == 0) {
        // Child process logic
        printf("Child process (PID %d) running and exiting with status %d.\n", getpid(), CHILD_EXIT_CODE);
        // Terminate with a specific exit status
        exit(CHILD_EXIT_CODE);
    } else {
        // Parent process logic
        printf("Parent process (PID %d) waiting for child (PID %d)...\n", getpid(), child_pid);

        // Wait specifically for the child_pid to change state, blocking until it terminates (0 options)
        pid_t terminated_pid = waitpid(child_pid, &status, 0);

        if (terminated_pid == -1) {
            perror("waitpid error");
            return 1;
        } else if (terminated_pid == child_pid) {
            printf("Child process %d terminated.\n", terminated_pid);

            // Check and interpret the status
            if (WIFEXITED(status)) {
                printf("Child exited normally with status: %d\n", WEXITSTATUS(status));
            } else if (WIFSIGNALED(status)) {
                printf("Child terminated by signal: %d\n", WTERMSIG(status));
            } else {
                printf("Child terminated abnormally.\n");
            }
        }
    }

    return 0;
}
